import{_ as e,o as s,c as n,a5 as i}from"./chunks/framework.D4tbZp_W.js";const b=JSON.parse('{"title":"知识地图：先建立问题，再建立目录","description":"","frontmatter":{},"headers":[],"relativePath":"guide/knowledge-map.md","filePath":"guide/knowledge-map.md","lastUpdated":1786328197000}'),l={name:"guide/knowledge-map.md"};function r(t,a,p,d,o,c){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="知识地图-先建立问题-再建立目录" tabindex="-1">知识地图：先建立问题，再建立目录 <a class="header-anchor" href="#知识地图-先建立问题-再建立目录" aria-label="Permalink to “知识地图：先建立问题，再建立目录”">​</a></h1><p>知识地图不是学科目录的复制品，而是一组你会反复遇到的问题。好的地图能让新材料快速找到位置，也能暴露现有认知的空白。</p><h2 id="从长期问题开始" tabindex="-1">从长期问题开始 <a class="header-anchor" href="#从长期问题开始" aria-label="Permalink to “从长期问题开始”">​</a></h2><p>先写下 3—5 个未来半年仍然重要的问题，例如：</p><ul><li>怎样稳定地交付高质量产品？</li><li>怎样让团队决策有据可查？</li><li>怎样理解并应用生成式 AI？</li></ul><h2 id="用三层结构保持简单" tabindex="-1">用三层结构保持简单 <a class="header-anchor" href="#用三层结构保持简单" aria-label="Permalink to “用三层结构保持简单”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>主题</span></span>
<span class="line"><span>├── 核心概念</span></span>
<span class="line"><span>├── 方法与工具</span></span>
<span class="line"><span>└── 案例与反例</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>当某个分支超过十篇内容，再考虑继续拆分。目录应当跟随内容生长，而不是提前设计到最细粒度。</p><h2 id="每月做一次断舍离" tabindex="-1">每月做一次断舍离 <a class="header-anchor" href="#每月做一次断舍离" aria-label="Permalink to “每月做一次断舍离”">​</a></h2><p>删除失效链接，合并重复结论，把已经不再重要的主题移入归档。整理的目标不是保持“整齐”，而是维持检索和判断效率。</p>`,10)])])}const m=e(l,[["render",r]]);export{b as __pageData,m as default};
